diff --git a/src/items/borrow.ts b/src/items/borrow.ts
index 8981259..375acf1 100644
--- a/src/items/borrow.ts
+++ b/src/items/borrow.ts
@@ -3,10 +3,12 @@ import type { Item, Member } from "../db";
 export type Decision = { ok: true } | { ok: false; reason: string };

 // Can this member take this item home now?
-// The member is not read yet. Issue 5 adds the induction rule that reads it.
-// biome-ignore lint/correctness/noUnusedFunctionParameters: issue 5 needs this input.
+// A class-C tool also needs the member to have done the "C" induction.
 export function canBorrow(member: Member, item: Item): Decision {
   if (item.status === "repair") return { ok: false, reason: `${item.name} is being repaired` };
   if (item.status === "out") return { ok: false, reason: `${item.name} is already out` };
+  if (item.safety_class === "C" && !member.inductions.includes("C")) {
+    return { ok: false, reason: `${item.name} needs an induction first` };
+  }
   return { ok: true };
 }
diff --git a/tests/items/borrow.test.ts b/tests/items/borrow.test.ts
index 75ab106..1c2d65a 100644
--- a/tests/items/borrow.test.ts
+++ b/tests/items/borrow.test.ts
@@ -27,3 +27,37 @@ test("a free class-A tool can go out", () => {
 test("a tool in repair cannot go out", () => {
   expect(canBorrow(member, { ...ladder, status: "repair" }).ok).toBe(false);
 });
+
+const chainsaw: Item = {
+  id: "saw-01",
+  name: "Chainsaw, 35 cm bar",
+  category: "garden",
+  safety_class: "C",
+  deposit_cents: 6000,
+  status: "in",
+};
+const inducted: Member = { ...member, inductions: ["C"] };
+
+test("a member without the C induction cannot take a class-C tool", () => {
+  expect(canBorrow(member, chainsaw).ok).toBe(false);
+});
+
+test("the refusal names the tool and says an induction is needed", () => {
+  const decision = canBorrow(member, chainsaw);
+  if (decision.ok) throw new Error("expected a refusal");
+  expect(decision.reason).toContain("Chainsaw");
+  expect(decision.reason.toLowerCase()).toContain("induction");
+});
+
+test("a member with the C induction can take a class-C tool that is in", () => {
+  expect(canBorrow(inducted, chainsaw)).toEqual({ ok: true });
+});
+
+test("a member with no inductions can still take a class-B tool", () => {
+  expect(canBorrow(member, { ...ladder, safety_class: "B" })).toEqual({ ok: true });
+});
+
+test("an inducted member still cannot take a class-C tool that is out or in repair", () => {
+  expect(canBorrow(inducted, { ...chainsaw, status: "out" }).ok).toBe(false);
+  expect(canBorrow(inducted, { ...chainsaw, status: "repair" }).ok).toBe(false);
+});

